// SHARED canonical cross-language byte+digest vectors for the request-projection
// protocol. GENERATED by the shipped TypeScript implementation of
// canonical-projection.ts over hand-authored descriptors, and byte-identical to
// the Python copy in crq_repair/canonical_vectors.json (compared field for field
// against the CRQ union a13c6e4c: 26 positives and 13 refusals, identical names,
// identical order, identical bytesHex/sha256). The Python reproduction test
// (test_canonical_projection.py) PASSED over that union under an independent
// runner, so this vector set already has executed Python-side equality. The
// TypeScript side is NOT executed in this lane (execution is centralized on
// Neptune) and this pair has no independent review of this head, so no
// interoperability is claimed here.
//
// `value` descriptors are language-neutral; each side decodes them with its own
// small helper (ints/floats are decimal strings so no reader depends on JSON
// number precision). `refusals` are values both languages MUST refuse to encode.
// `decoderRefusals` (Python only; see crq_repair/canonical_vectors.json) list
// byte strings the Python strict decoder must refuse.

export type CanonicalVectorValue =
  | { readonly t: 'null' }
  | { readonly t: 'bool'; readonly v: boolean }
  | { readonly t: 'int'; readonly v: string }
  | { readonly t: 'float'; readonly v: string }
  | { readonly t: 'str'; readonly v: string }
  | { readonly t: 'arr'; readonly v: readonly CanonicalVectorValue[] }
  | { readonly t: 'map'; readonly v: readonly (readonly [string, CanonicalVectorValue])[] }
  | { readonly t: 'cycle' }
  | { readonly t: 'mapint' }
  | { readonly t: 'set' }
  | { readonly t: 'bytes' }
  | { readonly t: 'nonfinite' };

export interface CanonicalProjectionPositiveVector {
  readonly name: string;
  readonly value: CanonicalVectorValue;
  readonly bytesHex: string;
  readonly sha256: string;
}

export interface CanonicalProjectionRefusalVector {
  readonly name: string;
  readonly value: CanonicalVectorValue;
}

